'use client';

import { useSearchParams, useRouter } from 'next/navigation';
import { useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { getProducts } from '@/api/product';
import Header from '@/components/Header';
import ProductCard from '@/components/product/ProductCard';
import Pagination from '@/components/product/Pagination';

interface Product {
  id: number;
  name: string;
  price: number;
  thumbnail: string;
  category?: { name: string };
}

export default function ProductsPage() {
  const searchParams = useSearchParams();
  const router = useRouter();
  const keywordParam = searchParams.get('keyword') || '';
  const pageParam = Number(searchParams.get('page') || '1');

  const [keyword, setKeyword] = useState(keywordParam);
  const [page, setPage] = useState(pageParam);

  const { data, isLoading, error } = useQuery({
    queryKey: ['products', keyword, page],
    queryFn: () => getProducts({ page, limit: 12, keyword: keyword || undefined }),
  });

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    setPage(1);
    const params = new URLSearchParams();
    if (keyword) params.set('keyword', keyword);
    router.push(`/products${params.toString() ? `?${params}` : ''}`);
  };

  const handlePageChange = (newPage: number) => {
    setPage(newPage);
    const params = new URLSearchParams();
    params.set('page', String(newPage));
    if (keyword) params.set('keyword', keyword);
    router.push(`/products?${params}`);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const products = data?.items || [];
  const totalPages = data?.total_pages || 1;

  return (
    <div className="min-h-screen bg-white">
      <Header />

      {/* Page Content */}
      <div className="max-w-7xl mx-auto px-8 py-8">
        {/* Page Title & Search */}
        <div className="flex items-center justify-between mb-6">
          <h1 className="text-2xl font-bold">Tất cả sản phẩm</h1>
          <form onSubmit={handleSearch} className="flex gap-2">
            <input
              type="text"
              placeholder="Tìm kiếm sản phẩm..."
              value={keyword}
              onChange={(e) => setKeyword(e.target.value)}
              className="w-64 px-4 py-2 border rounded-lg text-sm"
            />
            <button
              type="submit"
              className="px-4 py-2 bg-black text-white rounded-lg text-sm hover:bg-gray-800 transition-colors"
            >
              Tìm kiếm
            </button>
            {keyword && (
              <button
                type="button"
                onClick={() => {
                  setKeyword('');
                  setPage(1);
                  router.push('/products');
                }}
                className="px-4 py-2 border rounded-lg text-sm hover:bg-gray-50 transition-colors"
              >
                Xóa
              </button>
            )}
          </form>
        </div>

        {/* Products Grid */}
        {isLoading ? (
          <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
            {[...Array(12)].map((_, i) => (
              <div key={i} className="animate-pulse">
                <div className="h-48 bg-gray-200 rounded-lg mb-4" />
                <div className="h-4 bg-gray-200 rounded w-3/4 mb-2" />
                <div className="h-4 bg-gray-200 rounded w-1/2" />
              </div>
            ))}
          </div>
        ) : error ? (
          <div className="text-center py-12 text-red-500">
            Đã xảy ra lỗi khi tải sản phẩm
          </div>
        ) : products.length === 0 ? (
          <div className="text-center py-12 text-gray-500">
            Không tìm thấy sản phẩm nào
          </div>
        ) : (
          <>
            <p className="text-sm text-gray-500 mb-4">
              Hiển thị {products.length} sản phẩm
            </p>
            <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
              {products.map((product: Product) => (
                <ProductCard key={product.id} product={product} />
              ))}
            </div>
            {totalPages > 1 && (
              <div className="mt-8">
                <Pagination
                  currentPage={page}
                  totalPages={totalPages}
                  onPageChange={handlePageChange}
                />
              </div>
            )}
          </>
        )}
      </div>
    </div>
  );
}
